void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;  // Slightly more aggressive reduction than original 0.9
    rephase_limit += 16384;  // Double the original increment

    // Update saved phases based on recent assignments during this phase
    for (int i = 1; i <= vars; i++) {
        if (value[i] != 0) {  // Variable has been assigned in current search
            saved[i] = value[i];  // Save current assignment as preferred phase
        } else if (rand() % 100 < 30) {  // 30% chance to randomize unassigned vars
            saved[i] = rand() % 2 ? 1 : -1;
        }
        // Otherwise keep existing saved phase
    }
}
